        let temp = TempDir::new().unwrap();
        let root = Arc::new(temp.path().to_path_buf());

        // Seed the cache so readers always have something
        let store = CacheStore::new(temp.path());
        store
            .store("http:test", "hot-entry", "initial-content", 3600)
            .unwrap();

        let barrier = Arc::new(std::sync::Barrier::new(8));

        let handles: Vec<_> = (0..8)
            .map(|i| {
                let root = Arc::clone(&root);
                let barrier = Arc::clone(&barrier);
                std::thread::spawn(move || {
                    let store = CacheStore::new(root.as_ref());
                    barrier.wait();

                    if i % 2 == 0 {
                        // Writer
                        let content = format!("writer-{}-payload", i);
                        store
                            .store("http:test", "hot-entry", &content, 3600)
                            .unwrap();
                    } else {
                        // Reader
                        for _ in 0..20 {
                            if let Ok(Some(entry)) = store.load("http:test", "hot-entry") {
                                if let Ok(content) = store.read_content(&entry) {
                                    // Content must be a complete, valid string
                                    assert!(
                                        content == "initial-content"
                                            || content.starts_with("writer-"),
                                        "read partial/corrupt data: {}",
                                        content
                                    );
                                }
                            }
                        }
                    }
                })
            })
            .collect();

        for h in handles {
            h.join().unwrap();
        }
    }
}

