    #[test]
    fn no_temp_files_left_after_store() {
        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());

        store
            .store("http:test", "template1", "content", 3600)
            .unwrap();

        let tmp_files: Vec<_> = fs::read_dir(temp.path())
            .unwrap()
            .filter_map(|e| e.ok())
            .filter(|e| {
                e.file_name()
                    .to_string_lossy()
                    .starts_with(".tmp.")
            })
            .collect();

        assert!(tmp_files.is_empty(), "temp files should be cleaned up");
    }

    #[test]
    fn update_content_atomically() {
        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());

        let entry = store
            .store("http:test", "template1", "original", 3600)
            .unwrap();

        store.update_content(&entry, "updated").unwrap();

        let content = store.read_content(&entry).unwrap();
        assert_eq!(content, "updated");
    }

    #[test]
    fn concurrent_stores_produce_consistent_entries() {
        let temp = TempDir::new().unwrap();
        let root = temp.path().to_path_buf();
        let root = Arc::new(root);

        let handles: Vec<_> = (0..8)
            .map(|i| {
                let root = Arc::clone(&root);
                std::thread::spawn(move || {
                    let store = CacheStore::new(root.as_ref());
                    let content = format!("content-from-thread-{}", i);
                    store
                        .store("http:test", "shared-template", &content, 3600)
                        .unwrap();
                })
            })
            .collect();

        for h in handles {
            h.join().unwrap();
        }

        let store = CacheStore::new(temp.path());
        let entry = store
            .load("http:test", "shared-template")
            .unwrap()
            .expect("entry should exist");
        let content = store.read_content(&entry).unwrap();

        // Content must match one of the thread writes exactly
        assert!(
            content.starts_with("content-from-thread-"),
            "content should be a complete write, got: {}",
            content
        );
        assert_eq!(
            entry.metadata.size_bytes,
            content.len() as u64,
            "metadata size must match actual content"
        );
    }

    #[test]
    fn concurrent_stores_to_different_entries() {
        let temp = TempDir::new().unwrap();
        let root = Arc::new(temp.path().to_path_buf());

        let handles: Vec<_> = (0..8)
            .map(|i| {
                let root = Arc::clone(&root);
                std::thread::spawn(move || {
                    let store = CacheStore::new(root.as_ref());
                    let name = format!("template-{}", i);
                    let content = format!("content-{}", i);
                    store
                        .store("http:test", &name, &content, 3600)
                        .unwrap();
                })
            })
            .collect();

        for h in handles {
            h.join().unwrap();
        }

        let store = CacheStore::new(temp.path());
        let entries = store.list().unwrap();
        assert_eq!(entries.len(), 8);

        for i in 0..8 {
            let name = format!("template-{}", i);
            let entry = store.load("http:test", &name).unwrap().unwrap();
            let content = store.read_content(&entry).unwrap();
            assert_eq!(content, format!("content-{}", i));
        }
    }

    #[test]
    fn concurrent_store_and_read_never_sees_partial_data() {
        let temp = TempDir::new().unwrap();
        let root = Arc::new(temp.path().to_path_buf());

        // Seed the cache so readers always have something
        let store = CacheStore::new(temp.path());
        store
            .store("http:test", "hot-entry", "initial-content", 3600)
            .unwrap();

        let barrier = Arc::new(std::sync::Barrier::new(8));

        let handles: Vec<_> = (0..8)
            .map(|i| {
                let root = Arc::clone(&root);
                let barrier = Arc::clone(&barrier);
                std::thread::spawn(move || {
                    let store = CacheStore::new(root.as_ref());
                    barrier.wait();

                    if i % 2 == 0 {
                        // Writer
                        let content = format!("writer-{}-payload", i);
                        store
                            .store("http:test", "hot-entry", &content, 3600)
                            .unwrap();
                    } else {
                        // Reader
                        for _ in 0..20 {
                            if let Ok(Some(entry)) = store.load("http:test", "hot-entry") {
                                if let Ok(content) = store.read_content(&entry) {
                                    // Content must be a complete, valid string
                                    assert!(
                                        content == "initial-content"
                                            || content.starts_with("writer-"),
                                        "read partial/corrupt data: {}",
                                        content
                                    );
                                }
                            }
                        }
                    }
                })
            })
            .collect();

        for h in handles {
            h.join().unwrap();
        }
    }
}

